CREATE TRIGGER timeline_shape_dest_upd BEFORE UPDATE OF kind, geometry ON timeline_shapes
            WHEN NEW.kind = 'block' AND EXISTS (SELECT 1 FROM timeline_transitions t WHERE t.dest_shape_id = NEW.id
                 AND (t.path_style = 'follow_the_leader'
                      OR json_extract(NEW.geometry, '$.rows') * json_extract(NEW.geometry, '$.cols') < t.slot_count))
            BEGIN SELECT RAISE(ABORT, 'E-T3/E-T4: shape change invalidates a transition using it'); END;

-- statement
CREATE TRIGGER timeline_tl_contains_upd BEFORE UPDATE OF start_beat, end_beat ON timelines
            WHEN EXISTS (SELECT 1 FROM timeline_transitions t WHERE t.timeline_id = NEW.id
                         AND (t.start_beat < NEW.start_beat OR t.end_beat > NEW.end_beat))
            BEGIN SELECT RAISE(ABORT, 'E-T1: timeline would no longer contain its transitions'); END;

