                          OR json_extract(s.geometry, '$.rows') * json_extract(s.geometry, '$.cols') < NEW.slot_count))
            BEGIN SELECT RAISE(ABORT, 'E-T3/E-T4: block shape used for FTL or over capacity'); END;

