            BEGIN SELECT RAISE(ABORT, 'E-A1/E-A2: assignment outside transition range or slot_count'); END;

-- statement
CREATE TRIGGER timeline_asn_overlap_ins BEFORE INSERT ON timeline_assignments
            WHEN EXISTS (SELECT 1 FROM timeline_assignments a WHERE a.marcher_id = NEW.marcher_id
                         AND a.layer = NEW.layer
                         AND a.start_beat < NEW.end_beat AND NEW.start_beat < a.end_beat)
            BEGIN SELECT RAISE(ABORT, 'E-A3: overlapping assignments for one marcher at the same layer'); END;

-- statement
CREATE TRIGGER timeline_asn_overlap_upd BEFORE UPDATE ON timeline_assignments
            WHEN EXISTS (SELECT 1 FROM timeline_assignments a WHERE a.id <> NEW.id
                         AND a.marcher_id = NEW.marcher_id AND a.layer = NEW.layer
                         AND a.start_beat < NEW.end_beat AND NEW.start_beat < a.end_beat)
            BEGIN SELECT RAISE(ABORT, 'E-A3: overlapping assignments for one marcher at the same layer'); END;

-- statement
CREATE TRIGGER timeline_sd_ins BEFORE INSERT ON timeline_slot_destinations
            
        WHEN NOT EXISTS (SELECT 1 FROM timeline_transitions t WHERE t.id = NEW.transition_id
                         AND t.dest_shape_id IS NULL AND NEW.slot_index < t.slot_count)
            BEGIN SELECT RAISE(ABORT, 'E-T6: destination row on a shaped transition or outside slot_count'); END;

-- statement
CREATE TRIGGER timeline_sd_upd BEFORE UPDATE ON timeline_slot_destinations
            
        WHEN NOT EXISTS (SELECT 1 FROM timeline_transitions t WHERE t.id = NEW.transition_id
                         AND t.dest_shape_id IS NULL AND NEW.slot_index < t.slot_count)
            BEGIN SELECT RAISE(ABORT, 'E-T6: destination row on a shaped transition or outside slot_count'); END;

-- statement
CREATE TRIGGER prevent_utility_deletion
            BEFORE DELETE ON utility
            FOR EACH ROW
            WHEN OLD.id = 0
            BEGIN
                SELECT RAISE(FAIL, 'Deletion not allowed for the utility record.');
            END;
